'use client';
import {useCallback,useEffect,useMemo,useState} from 'react';
import {Swords,Users,ShieldCheck,Plus,ArrowUpRight,ArrowRight,Flame,BookOpen,Check,Copy,Lock,Target,X,ChevronRight,Trophy,Menu,Search,Bell,UserRound,Database,Compass,Flag,MessageCircle,ThumbsUp,AlertTriangle,Edit3,Trash2,ExternalLink,GitCompareArrows,Eye,Settings} from 'lucide-react';
import {SidebarProvider,Sidebar,SidebarHeader,SidebarContent,SidebarFooter,SidebarMenu,SidebarMenuItem,SidebarMenuButton,SidebarTrigger} from '@/components/ui/sidebar';
import {Dialog,DialogContent,DialogTitle,DialogDescription} from '@/components/ui/dialog';
