function Header({eyebrow,title,copy,action}:{eyebrow:string;title:string;copy:string;action?:React.ReactNode}){return <div className="page-heading"><div><div className="eyebrow">{eyebrow}</div><h1>{title}</h1><p>{copy}</p></div>{action}</div>}
function Arena({data,filter,setFilter,voted,openBattle,onCreate,onSquads}:any){return <><Header eyebrow="PICK A SIDE. MAKE YOUR CASE." title="The Battle Arena" copy="Structured matchups, explicit rules, difficulty votes, and evidence-backed arguments." action={<button className="primary" onClick={onCreate}><Plus size={18}/>Create battle</button>}/><div className="arena-layout"><div><section className="feature"><div className="feature-lines"/><div className="feature-copy"><span className="feature-label"><Flame size={15}/> FEATURED MATCHUP</span><h2>GOKU<span>VS.</span>ICHIGO</h2><p>Same rules. Clear versions.<br/>Make the case with evidence.</p><button className="light-button" onClick={()=>openBattle(starterBattles[0])}>Enter the debate <ArrowUpRight size={18}/></button></div><span className="feature-kanji">対決</span><img className="feature-character" src="/ichigo.png" alt="Ichigo Kurosaki holding his sword"/><a className="art-credit" href="https://bleach-anime.com/character/" target="_blank" rel="noreferrer">Art: BLEACH official</a></section><div className="section-heading"><h2>Open matchups <span>{data.battles.length}</span></h2><Tabs value={filter} onValueChange={setFilter}><TabsList><TabsTrigger value="all">All</TabsTrigger><TabsTrigger value="voted">Your votes</TabsTrigger></TabsList></Tabs></div><div className="battles">{data.battles.filter((b:Battle)=>filter==='all'||voted.has(b.id)).map((b:Battle)=>{const result=data.results.find((r:BattleResult)=>r.battle===b.id),total=result?.total||0,location=b.location==='custom'?(b.customLocation||'Custom'):LOCATION_LABELS[b.location];return <button className="battle-card" key={b.id} onClick={()=>openBattle(b)}><div className="battle-top"><span><Swords size={14}/>{b.isLegacy?(b.legacyVictory||'LEGACY RULES'):BATTLE_TYPE_LABELS[b.battleType]}</span><span>{voted.has(b.id)?'VOTED':b.created?'COMMUNITY':'STARTER'}</span></div><div className="fighter-pair"><div><Avatar name={b.a} color={fighter(b.fighterAId||b.a)?.color}/><strong>{b.a}</strong><small>{b.versionA}</small></div><b className="vs">VS</b><div><Avatar name={b.b} color={fighter(b.fighterBId||b.b)?.color}/><strong>{b.b}</strong><small>{b.versionB}</small></div></div><div className="rule-chips"><span>{SPEED_LABELS[b.speed]} speed</span>{b.isLegacy?<span>Legacy rules</span>:<><span>{location}</span><span>{PREP_LABELS[b.prepTime]} prep</span></>}</div><div className="battle-bottom"><span>{total} vote{total===1?'':'s'}</span><span>Join debate <ArrowRight size={14}/></span></div></button>})}</div></div><aside className="right-rail"><section className="challenge-card"><div className="eyebrow"><Trophy size={16}/> DAILY SQUAD CHALLENGE</div><div className="challenge-mark"><Target size={42}/></div><h2>Can your squad<br/>take down the boss?</h2><p>{data.challenge.boss}</p><div className="challenge-stats"><div><strong>20</strong><small>POINT BUDGET</small></div><div><strong>5</strong><small>FIGHTERS</small></div></div><button className="primary full" onClick={onSquads}>Build your squad <ArrowRight size={16}/></button></section></aside></div></>}
function Characters({query,setQuery,results,open,createBattle}:any){return <><Header eyebrow="CANON NOTES. CLEAR ENDPOINTS." title="Character database" copy="Search forms, abilities, story endpoints, and source pages before creating a matchup."/><div className="searchbox"><Search size={19}/><input value={query} onChange={e=>setQuery(e.target.value)} placeholder="Search character, series, ability, or tag"/></div><div className="character-grid">{results.map((f:any)=><article className="panel character-card" key={f.id}><div className="character-head"><Avatar name={f.name} color={f.color}/><div><h2>{f.name}</h2><p>{f.series}</p></div><span className="cost">{f.cost}<small> PTS</small></span></div><div className="role">{f.role}</div><p>{f.ability}</p><div className="chips">{f.forms.slice(0,3).map((x:string)=><span key={x}>{x}</span>)}</div><small className="endpoint">Endpoint: {f.endpoint}</small><div className="card-actions"><button className="secondary" onClick={()=>open(f)}>View record</button><button className="primary" onClick={()=>createBattle(f.id)}>Use in battle</button></div></article>)}</div></>}
function Tournaments({data,busy,vote}:any){if(!data?.matches)return <Loading/>;const active=data.matches.filter((m:any)=>m.active);return <><Header eyebrow={`${data.week} · ${data.phase.toUpperCase()}`} title={data.title} copy="Vote through the weekly bracket. Winners advance when the next UTC round opens."/><div className="tournament-layout"><section><div className="round-title"><h2>Current round</h2><span>{data.phase}</span></div><div className="match-grid">{active.map((m:any)=><article className="panel bracket-match" key={m.id}><small>MATCH {m.id.toUpperCase()}</small><TournamentFighter id={m.a} votes={m.aVotes} selected={m.myPick===m.a} onClick={()=>vote(data.week,m.id,m.a)} disabled={busy}/><b>VS</b><TournamentFighter id={m.b} votes={m.bVotes} selected={m.myPick===m.b} onClick={()=>vote(data.week,m.id,m.b)} disabled={busy}/></article>)}</div><h2 className="history-title">Full bracket</h2><div className="bracket-history">{data.matches.map((m:any)=><div key={m.id} className={m.active?'active':''}><span>{m.id.toUpperCase()}</span><strong>{fighter(m.a)?.name||m.a}</strong><em>{m.aVotes}–{m.bVotes}</em><strong>{fighter(m.b)?.name||m.b}</strong></div>)}</div></section><aside className="panel leaderboard"><Trophy size={30}/><h2>Weekly leaderboard</h2>{data.leaderboard.map((x:any,i:number)=><div key={x.id}><b>{i+1}</b><Avatar name={fighter(x.id)?.name||x.id} color={fighter(x.id)?.color}/><span>{fighter(x.id)?.name||x.id}</span><strong>{x.votes}</strong></div>)}</aside></div></>}
function TournamentFighter({id,votes,selected,onClick,disabled}:any){const f=fighter(id);return <button className={'tournament-fighter '+(selected?'selected':'')} onClick={onClick} disabled={disabled}><Avatar name={f?.name||id} color={f?.color}/><div><strong>{f?.name||id}</strong><small>{f?.series}</small></div><b>{votes}</b>{selected&&<Check size={17}/>}</button>}
function Squads({data,shared,selected,members,points,toggle,squadName,setSquadName,strategy,setStrategy,busy,saveSquad,share,onChallenges}:any){return <><Header eyebrow="FIVE FIGHTERS. ONE PLAN." title="Build your dream squad" copy="Balance your budget, find your synergy, and challenge another fan." action={<button className="secondary" onClick={onChallenges}><GitCompareArrows size={17}/>Squad battles</button>}/><div className="squad-banner"><div><span className="eyebrow">TODAY’S BOSS · {data.challenge.day}</span><h2>{data.challenge.boss}</h2><p>{data.challenge.brief}</p></div><Target size={48}/></div>{shared&&<section className="panel shared"><span className="eyebrow">SHARED SQUAD</span><h2>{shared.name}</h2><p>{names(shared.members)}</p><p>{shared.strategy}</p></section>}<div className="squad-layout"><section><div className="fighter-grid">{fighters.map(f=><button key={f.id} className={'fighter-card '+(members.includes(f.id)?'selected':'')} onClick={()=>toggle(f.id)}><div className="fighter-card-top"><Avatar name={f.name} color={f.color}/><span className="cost">{f.cost}<small> PTS</small></span></div><h3>{f.name}</h3><small>{f.series}</small><div className="role">{f.role}</div><p>{f.ability}</p><span className="choose-icon">{members.includes(f.id)?<Check size={17}/>:<Plus size={17}/>}</span></button>)}</div></section><aside className="panel squad-summary"><div className="section-heading"><h2>Your lineup</h2><span>{members.length} / 5</span></div><div className="budget"><span>Point budget</span><strong>{points}<span> / 20</span></strong></div><Progress value={points/20*100}/><div className="slots">{Array.from({length:5},(_,i)=>selected[i]?<div className="slot filled" key={i}><Avatar name={selected[i].name} color={selected[i].color}/><div><strong>{selected[i].name}</strong><small>{selected[i].role} · {selected[i].cost} pts</small></div><button onClick={()=>toggle(selected[i].id)}><X size={16}/></button></div>:<div className="slot" key={i}><span className="slot-number">0{i+1}</span><span>Choose a fighter</span></div>)}</div><label>Squad name<input value={squadName} onChange={e=>setSquadName(e.target.value)} placeholder="Give your team a name"/></label><label>Battle plan<textarea value={strategy} onChange={e=>setStrategy(e.target.value)} placeholder="Explain roles, versions, and win condition."/></label><button className="primary full" disabled={busy||members.length!==5||squadName.length<1||strategy.length<10} onClick={saveSquad}>Save squad</button></aside></div><section className="saved-squads"><div className="section-heading"><h2>Your saved squads</h2></div>{data.squads.length?data.squads.map((s:Squad)=><div className="panel saved-squad" key={s.id}><div><h3>{s.name}</h3><p>{names(s.members)}</p><small>{s.strategy}</small></div><button className="secondary" onClick={()=>share('squad',s.id)}><Copy size={16}/>Share</button></div>):<p className="muted">Sign in and save five fighters to create your first squad.</p>}</section></>}
function Challenges({data,draft,setDraft,busy,create,vote}:any){if(!data)return <Loading/>;const squadOptions=(data.mySquads||[]).map((s:any)=>({value:s.id,label:s.name})),opponentOptions=(data.publicSquads||[]).filter((s:any)=>s.id!==draft.challengerSquad).map((s:any)=>({value:s.id,label:`${s.name} · @${s.handle}`}));return <><Header eyebrow="STRATEGY AGAINST STRATEGY." title="Squad battles" copy="Challenge another saved squad under the same rules, then let the community decide."/><section className="panel challenge-create"><h2>Open a challenge</h2><div className="form-grid"><label>Your squad<Pick value={draft.challengerSquad} onChange={v=>setDraft({...draft,challengerSquad:v})} items={squadOptions} label="Your squad"/></label><label>Opponent squad<Pick value={draft.opponentSquad} onChange={v=>setDraft({...draft,opponentSquad:v})} items={opponentOptions} label="Opponent squad"/></label></div><label>Battle rules<textarea value={draft.rules} onChange={e=>setDraft({...draft,rules:e.target.value})}/></label><button className="primary" disabled={busy||!draft.challengerSquad||!draft.opponentSquad} onClick={create}>Open challenge</button></section><div className="challenge-list">{data.challenges?.map((c:any)=><article className="panel versus-squads" key={c.id}><div className="challenge-rule"><span className="tag">OPEN CHALLENGE</span><p>{c.rules}</p></div><div className="squad-versus"><button onClick={()=>vote(c.id,'challenger')}><strong>{c.challengerName}</strong><small>@{c.challengerHandle||'anime_fan'}</small><p>{names(c.challengerMembers)}</p><b>{c.challengerVotes} votes</b></button><span>VS</span><button onClick={()=>vote(c.id,'opponent')}><strong>{c.opponentName}</strong><small>@{c.opponentHandle||'anime_fan'}</small><p>{names(c.opponentMembers)}</p><b>{c.opponentVotes} votes</b></button></div></article>)}{!data.challenges?.length&&<div className="empty-state">No squad challenges yet. Open the first one.</div>}</div></>}
function Clubs({club,clubId,setClubId,data,episode,setEpisode,postEpisode,setPostEpisode,body,setBody,busy,save,reload,report}:any){return <><Header eyebrow="GOOD CONVERSATIONS. NO JUMPING AHEAD." title="Spoiler-safe anime clubs" copy="Set your progress and see only discussions that are safe for you."/><div className="club-selector">{clubs.map(c=><button key={c.id} className={'panel club-select '+(clubId===c.id?'selected':'')} onClick={()=>setClubId(c.id)}><span className="club-tile" style={{color:c.color,background:c.color+'15'}}>{c.letters}</span><div><h3>{c.name}</h3><small>{c.season} · {c.episodes} episodes</small></div>{clubId===c.id&&<Check size={18}/>}</button>)}</div><div className="club-layout"><section className="panel discussions"><div className="section-heading"><h2>{club.name}</h2><span className="safe-badge"><ShieldCheck size={14}/>Episode {data?.episode||0} and earlier</span></div><p className="muted">{club.description}</p>{!data?<Loading/>:<><form className="post-form" onSubmit={async e=>{e.preventDefault();if(await save({action:'post',club:clubId,episode:Number(postEpisode),body},'Discussion posted.')){setBody('');reload()}}}><label>Start a conversation<textarea value={body} onChange={e=>setBody(e.target.value)} placeholder="What caught your attention?"/></label><div className="post-controls"><Pick value={postEpisode} onChange={setPostEpisode} items={Array.from({length:data.episode+1},(_,i)=>String(i))} label="Discussion episode"/><span className="muted small">Episode tag</span><button className="primary" disabled={busy||body.length<5}>Post</button></div></form>{data.posts?.map((p:any)=><article className="discussion" key={p.id}><div><Avatar name={p.displayName}/><strong>{p.displayName}</strong><a onClick={e=>e.preventDefault()}>@{p.handle}</a><span className="tag">Episode {p.episode}</span>{p.edited?<small>edited</small>:null}</div><p>{p.body}</p><div className="post-actions">{p.owned&&<button onClick={async()=>{const next=prompt('Edit your post',p.body);if(next&&await save({action:'edit_post',post:p.id,body:next},'Post updated.'))reload()}}><Edit3 size={14}/>Edit</button>}{p.owned&&<button onClick={async()=>{if(confirm('Delete this post?')&&await save({action:'delete_post',post:p.id},'Post deleted.'))reload()}}><Trash2 size={14}/>Delete</button>}<button onClick={()=>report('post',p.id)}><Flag size={14}/>Report</button></div></article>)}{data.locked>0&&<div className="locked"><Lock size={18}/>{data.locked} later-episode discussions are hidden.</div>}</>}</section><aside><section className="panel progress-panel"><ShieldCheck size={30}/><h2>Your spoiler shield</h2><p>What’s the last episode you finished?</p><Pick value={episode} onChange={setEpisode} items={Array.from({length:club.episodes+1},(_,i)=>String(i))} label="Last watched episode"/><button className="primary full" disabled={busy} onClick={async()=>{if(await save({action:'progress',club:clubId,episode:Number(episode)},'Viewing progress saved.'))reload()}}>Save progress</button><div className="club-rules"><h3>Club rules</h3>{(data?.rules||club.rules).map((r:string)=><p key={r}><Check size={14}/>{r}</p>)}</div></section></aside></div></>}
function Discover({data,save,reload,openProfile}:any){if(!data)return <Loading/>;return <><Header eyebrow="YOUR NEXT SHOW. YOUR KIND OF FANS." title="Discover" copy="Find people with overlapping favourites and recommendations shaped by your profile."/><div className="discover-layout"><section><h2>Fans with similar taste</h2><div className="fan-grid">{data.profiles?.map((p:any)=><button className="panel fan-card" key={p.handle} onClick={()=>openProfile(p.handle)}><Avatar name={p.displayName}/><div><h3>{p.displayName}</h3><small>@{p.handle}</small></div>{p.match!=null&&<strong>{p.match}% match</strong>}<p>{p.favoriteAnime.slice(0,3).join(' · ')||'Building their taste profile'}</p></button>)}{!data.profiles?.length&&<div className="empty-state">As public profiles join, your closest taste matches will appear here.</div>}</div></section><aside><h2>Recommended for you</h2><div className="recommendations">{data.recommendations?.map((a:any)=>{const current=data.watchlist?.find((w:any)=>w.anime===a.id)?.status;return <article className="panel" key={a.id}><span className="tag">{a.genres.join(' · ')}</span><h3>{a.title}</h3><p>{a.why}</p><Pick value={current||'remove'} onChange={async status=>{if(await save({action:'watchlist',anime:a.id,status},'Watchlist updated.'))reload()}} items={[{value:'remove',label:'Not saved'},{value:'planned',label:'Plan to watch'},{value:'watching',label:'Watching'},{value:'completed',label:'Completed'}]} label={'Watchlist status for '+a.title}/></article>})}</div></aside></div></>}
function ProfilePage({user,current,page,draft,setDraft,busy,signIn,saveProfile,share}:any){if(!user)return <><Header eyebrow="YOUR ANIME IDENTITY." title="Create your fan profile" copy="Sign in to save favourites, battle history, squads, and club progress."/><button className="primary" onClick={signIn}>Sign in with ChatGPT</button></>;const p=page?.profile||current;if(!current)return <ProfileForm draft={draft} setDraft={setDraft} busy={busy} saveProfile={saveProfile}/>;return <><Header eyebrow="YOUR ANIME IDENTITY." title={p?.displayName||current.displayName} copy={p?`@${p.handle}`:'Loading profile…'} action={p&&<button className="secondary" onClick={()=>share('profile',p.handle)}><Copy size={16}/>Share profile</button>}/>{p?.owned&&<ProfileForm draft={draft} setDraft={setDraft} busy={busy} saveProfile={saveProfile} compact/>}<div className="profile-layout"><section className="panel profile-hero"><Avatar name={p?.displayName||'Fan'}/><h2>{p?.displayName}</h2><span>@{p?.handle}</span><p>{p?.bio||'No bio yet.'}</p><h3>Favourite anime</h3><div className="chips">{p?.favoriteAnime.map((x:string)=><span key={x}>{x}</span>)}</div><h3>Favourite characters</h3><div className="chips">{p?.favoriteCharacters.map((id:string)=><span key={id}>{fighter(id)?.name||id}</span>)}</div></section><section><div className="profile-stats"><div className="panel"><strong>{page?.record?.total||0}</strong><span>Battle votes</span></div><div className="panel"><strong>{page?.squads?.length||0}</strong><span>Saved squads</span></div><div className="panel"><strong>{page?.progress?.length||0}</strong><span>Active clubs</span></div></div><h2 className="history-title">Saved squads</h2>{page?.squads?.map((s:Squad)=><article className="panel saved-squad" key={s.id}><div><h3>{s.name}</h3><p>{names(s.members)}</p><small>{s.strategy}</small></div></article>)}</section></div></>}
function ProfileForm({draft,setDraft,busy,saveProfile,compact}:any){const animeOptions=['Dragon Ball','Bleach','Naruto','One Piece','Demon Slayer','Attack on Titan','Jujutsu Kaisen','My Hero Academia','Chainsaw Man','Black Clover'];function toggle(list:string[],v:string){return list.includes(v)?list.filter(x=>x!==v):list.length<8?[...list,v]:list}return <section className={'panel profile-form '+(compact?'compact':'')}><h2>{compact?'Edit profile':'Set up your public profile'}</h2><div className="form-grid"><label>Handle<input value={draft.handle} onChange={e=>setDraft({...draft,handle:e.target.value.toLowerCase().replace(/[^a-z0-9_]/g,'')})} placeholder="anime_handle"/></label><label>Display name<input value={draft.displayName} onChange={e=>setDraft({...draft,displayName:e.target.value})}/></label></div><label>Bio<textarea value={draft.bio} onChange={e=>setDraft({...draft,bio:e.target.value})} placeholder="Your genres, debate style, and current watchlist."/></label><label>Favourite anime<div className="choice-chips">{animeOptions.map(x=><button type="button" key={x} className={draft.favoriteAnime.includes(x)?'selected':''} onClick={()=>setDraft({...draft,favoriteAnime:toggle(draft.favoriteAnime,x)})}>{x}</button>)}</div></label><label>Favourite characters<div className="choice-chips">{fighters.slice(0,14).map(f=><button type="button" key={f.id} className={draft.favoriteCharacters.includes(f.id)?'selected':''} onClick={()=>setDraft({...draft,favoriteCharacters:toggle(draft.favoriteCharacters,f.id)})}>{f.name}</button>)}</div></label><button className="primary" disabled={busy||draft.handle.length<3||!draft.displayName} onClick={saveProfile}>Save profile</button></section>}
function Notifications({data,save,reload}:any){if(!data)return <Loading/>;return <><Header eyebrow="REPLIES. CHALLENGES. NEW ROUNDS." title="Notifications" copy="Everything that needs your attention, in one place." action={data.unread>0&&<button className="secondary" onClick={async()=>{if(await save({action:'notification_read',id:'all'}))reload()}}>Mark all read</button>}/><div className="notification-list">{data.notifications?.map((n:any)=><a className={'panel notification '+(!n.read?'unread':'')} key={n.id} href={n.link} onClick={()=>void save({action:'notification_read',id:n.id})}><span>{n.kind==='reply'?<MessageCircle/>:n.kind==='challenge'?<GitCompareArrows/>:n.kind==='club'?<ShieldCheck/>:<Trophy/>}</span><div><strong>{n.message}</strong><small>{new Date(n.created).toLocaleString()}</small></div><ChevronRight/></a>)}{!data.notifications?.length&&<div className="empty-state">You are caught up.</div>}</div></>}
function Moderation({data,save,reload}:any){if(!data)return <Loading/>;return <><Header eyebrow="KEEP THE COMMUNITY FAIR." title="Moderation queue" copy="Review reported content, remove violations, and resolve reports."/><div className="report-list">{data.reports?.map((r:any)=><article className="panel" key={r.id}><span className="tag">{r.subjectType}</span><h3>{r.reason}</h3><small>Subject: {r.subjectId}</small><div className="button-row"><button className="secondary" onClick={async()=>{if(await save({action:'moderation',report:r.id,decision:'dismissed',deleteContent:false},'Report dismissed.'))reload()}}>Dismiss</button><button className="primary" onClick={async()=>{if(await save({action:'moderation',report:r.id,decision:'resolved',deleteContent:true},'Content removed and report resolved.'))reload()}}>Remove content</button></div></article>)}{!data.reports?.length&&<div className="empty-state">No open reports.</div>}</div></>}
function BattleDialog({active,close,data,side,setSide,difficulty,setDifficulty,reason,setReason,evidence,setEvidence,busy,save,reload,share,commentDrafts,setCommentDrafts,evidenceDrafts,setEvidenceDrafts,report}:any){
 if(!active)return null;
 const result=data.results.find((r:BattleResult)=>r.battle===active.id)||{a:0,b:0,draw:0,total:0,difficulty:{a:{},b:{}}};
 const pct=(n:number)=>result.total?Math.round(n/result.total*100):0;
 const location=active.location==='custom'?(active.customLocation||'Custom'):LOCATION_LABELS[active.location];
 const winnerLabel=(argument:BattleArgument)=>argument.side==='a'?active.a:argument.side==='b'?active.b:'Draw / Inconclusive';
 const chooseSide=(next:VoteSide)=>{setSide(next);if(next==='draw')setDifficulty('inconclusive');else if(difficulty==='inconclusive')setDifficulty('')};
 const voteReady=side==='draw'?difficulty==='inconclusive':Boolean(difficulty&&difficulty!=='inconclusive');
 return <Dialog open={!!active} onOpenChange={o=>!o&&close()}><DialogContent className="modal battle-modal"><DialogTitle>{active.a} <span className="purple">vs.</span> {active.b}</DialogTitle><DialogDescription>Judge the matchup under the exact rules, then back the verdict with a source reference.</DialogDescription>
 <div className="matchup-head"><div><Avatar name={active.a} color={fighter(active.fighterAId||active.a)?.color}/><strong>{active.a}</strong><span>{active.versionA}</span></div><b>VS</b><div><Avatar name={active.b} color={fighter(active.fighterBId||active.b)?.color}/><strong>{active.b}</strong><span>{active.versionB}</span></div></div>
 {active.isLegacy?<div className="rules battle-rule-grid legacy-rules"><div><small>Win condition</small><strong>{active.legacyVictory||'Legacy battle'}</strong></div><div><small>Speed</small><strong>{SPEED_LABELS[active.speed]}</strong></div>{active.legacyTransformations&&<div><small>Transformations</small><strong>{active.legacyTransformations}</strong></div>}</div>:<div className="rules battle-rule-grid"><div><small>Battle type</small><strong>{BATTLE_TYPE_LABELS[active.battleType]}</strong></div><div><small>Location</small><strong>{location}</strong></div><div><small>Speed</small><strong>{SPEED_LABELS[active.speed]}</strong></div><div><small>Knowledge</small><strong>{KNOWLEDGE_LABELS[active.knowledge]}</strong></div><div><small>Prep time</small><strong>{PREP_LABELS[active.prepTime]}</strong></div><div><small>Transformations</small><strong>{active.transformationsAllowed?'Allowed':'Not allowed'}</strong></div><div><small>Equipment</small><strong>{active.standardEquipment?'Standard equipment':'Not standard equipment'}</strong></div></div>}
 {active.notes&&<p className="muted">{active.notes}</p>}
 <section className="community-verdict"><div className="section-heading"><h3>Community verdict</h3><span>{result.total} vote{result.total===1?'':'s'}</span></div>{result.total?<div className="results"><div><span><b>{active.a}</b><strong>{pct(result.a)}%</strong></span><Progress value={pct(result.a)}/></div><div><span><b>{active.b}</b><strong>{pct(result.b)}%</strong></span><Progress value={pct(result.b)}/></div><div><span><b>Draw / Inconclusive</b><strong>{pct(result.draw)}%</strong></span><Progress value={pct(result.draw)}/></div></div>:<p className="muted">No votes yet. Be the first to judge this matchup.</p>}
 {result.total>0&&<div className="difficulty-distribution">{(['a','b'] as const).map(k=><div key={k}><strong>{k==='a'?active.a:active.b} votes</strong>{VOTE_DIFFICULTIES.filter(d=>d!=='inconclusive').map(d=><span key={d}>{DIFFICULTY_LABELS[d].replace(' Difficulty','')} <b>{result.difficulty[k]?.[d]||0}</b></span>)}</div>)}</div>}</section>
 <form className="battle-vote-form" onSubmit={async e=>{e.preventDefault();if(!voteReady)return;if(await save({action:'vote',battle:active.id,side,difficulty,reason,evidence},'Vote and argument saved.'))reload()}}><h3>Your vote</h3><div className="vote-side-grid"><button type="button" className={side==='a'?'selected':''} onClick={()=>chooseSide('a')}>{active.a}</button><button type="button" className={side==='b'?'selected':''} onClick={()=>chooseSide('b')}>{active.b}</button><button type="button" className={side==='draw'?'selected':''} onClick={()=>chooseSide('draw')}>Draw / Inconclusive</button></div>{side!=='draw'&&<><label>Difficulty</label><div className="difficulty-selector">{VOTE_DIFFICULTIES.filter(d=>d!=='inconclusive').map(d=><button type="button" key={d} className={difficulty===d?'selected':''} onClick={()=>setDifficulty(d)}>{DIFFICULTY_LABELS[d].replace(' Difficulty','')}</button>)}</div></>}<label>Make your case<textarea value={reason} onChange={e=>setReason(e.target.value)} placeholder="Explain how your pick wins under these exact rules."/></label><label>Episode or chapter reference<input value={evidence} onChange={e=>setEvidence(e.target.value)} placeholder="Series · episode / chapter · relevant feat"/></label><div className="button-row"><button className="primary" disabled={busy||!voteReady||reason.length<10||evidence.length<3}>Cast / update vote</button><button type="button" className="secondary" onClick={()=>share('battle',active.id)}><Copy size={16}/>Share</button></div></form>
 <div className="debate"><h3>Arguments and replies</h3>{data.debate?.map((a:BattleArgument)=>{const added=evidenceDrafts[a.user]||{reference:'',context:''};return <article key={a.argumentId}><div className="argument-head"><div><span className="tag">{winnerLabel(a)}</span><span className="argument-difficulty">{a.difficulty?DIFFICULTY_LABELS[a.difficulty]:'Legacy vote'}</span></div><a>@{a.handle}</a></div><p>{a.reason}</p><small><BookOpen size={13}/>{a.evidence}</small>{a.addedEvidence?.length>0&&<div className="argument-evidence"><strong>Additional evidence</strong>{a.addedEvidence.map(ev=><div key={ev.id}><span>@{ev.handle}</span><b>{ev.reference}</b>{ev.context&&<p>{ev.context}</p>}<button type="button" onClick={()=>report('evidence',ev.id)}><Flag size={12}/>Report</button></div>)}</div>}<div className="reaction-row"><button className={a.myReaction==='upvote'?'selected':''} onClick={async()=>{if(await save({action:'reaction',argumentId:a.argumentId,reaction:'upvote'}))reload()}}><ThumbsUp size={14}/>Agree {a.upvotes}</button><button className={a.myReaction==='dispute'?'selected':''} onClick={async()=>{if(await save({action:'reaction',argumentId:a.argumentId,reaction:'dispute'}))reload()}}><AlertTriangle size={14}/>Disagree {a.disputes}</button><button onClick={()=>report('argument',String(a.argumentId))}><Flag size={14}/>Report</button></div><details className="evidence-form"><summary><BookOpen size={14}/>Add evidence</summary><form onSubmit={async e=>{e.preventDefault();if(await save({action:'add_evidence',battle:active.id,argumentUser:a.user,reference:added.reference,context:added.context},'Evidence added.')){setEvidenceDrafts({...evidenceDrafts,[a.user]:{reference:'',context:''}});reload()}}}><input value={added.reference} onChange={e=>setEvidenceDrafts({...evidenceDrafts,[a.user]:{...added,reference:e.target.value}})} placeholder="Episode / chapter reference"/><textarea value={added.context} onChange={e=>setEvidenceDrafts({...evidenceDrafts,[a.user]:{...added,context:e.target.value}})} placeholder="Optional context for why this supports the argument"/><button className="secondary" disabled={busy||added.reference.trim().length<3}>Add evidence</button></form></details><div className="reply-list">{a.comments?.map(c=><div key={c.id}><b>@{c.handle}</b><p>{c.body}</p><button onClick={()=>report('comment',c.id)}><Flag size={12}/></button></div>)}</div><form className="reply-form" onSubmit={async e=>{e.preventDefault();const body=commentDrafts[a.argumentId]||'';if(await save({action:'comment',battle:active.id,argumentId:a.argumentId,body},'Reply posted.')){setCommentDrafts({...commentDrafts,[a.argumentId]:''});reload()}}}><input value={commentDrafts[a.argumentId]||''} onChange={e=>setCommentDrafts({...commentDrafts,[a.argumentId]:e.target.value})} placeholder="Reply to this argument"/><button className="secondary" disabled={(commentDrafts[a.argumentId]||'').length<3}>Reply</button></form></article>})}{!data.debate?.length&&<p className="muted">No arguments yet. Make the opening case.</p>}</div></DialogContent></Dialog>
}

function FighterPicker({label,value,exclude,onChange}:{label:string;value:string;exclude?:string;onChange:(id:string)=>void}){const [query,setQuery]=useState('');const selected=fighter(value),matches=fighters.filter(f=>f.id!==exclude&&(`${f.name} ${f.series} ${f.forms.join(' ')}`).toLowerCase().includes(query.toLowerCase())).slice(0,8);return <div className="fighter-selector"><label>{label}<input value={query} onChange={e=>setQuery(e.target.value)} placeholder={selected?`${selected.name} selected · search to change`:'Search character or series'}/></label>{selected&&<div className="fighter-selection"><Avatar name={selected.name} color={selected.color}/><div><strong>{selected.name}</strong><small>{selected.series} · {selected.role}</small><p>{selected.ability}</p></div></div>}<div className="fighter-options">{matches.map(f=><button type="button" key={f.id} className={value===f.id?'selected':''} onClick={()=>{onChange(f.id);setQuery('')}}><span>{f.name}</span><small>{f.series}</small></button>)}</div></div>}

function CreateBattle({open,setOpen,draft,setDraft,busy,save}:any){const fa=fighter(draft.fighterAId),fb=fighter(draft.fighterBId),location=draft.location==='custom'?(draft.customLocation||'Custom location'):LOCATION_LABELS[draft.location],valid=fa&&fb&&fa.id!==fb.id&&fa.forms.includes(draft.versionA)&&fb.forms.includes(draft.versionB)&&(draft.location!=='custom'||draft.customLocation?.trim());return <Dialog open={open} onOpenChange={setOpen}><DialogContent className="modal battle-builder"><DialogTitle>Create a structured matchup</DialogTitle><DialogDescription>Pick catalog fighters and versions, then lock the conditions before the debate starts.</DialogDescription><form onSubmit={e=>{e.preventDefault();save()}}><div className="fighter-builder-grid"><div><FighterPicker label="Fighter A" value={draft.fighterAId} exclude={draft.fighterBId} onChange={fighterAId=>setDraft({...draft,fighterAId,versionA:''})}/><label>Version<Pick value={draft.versionA} onChange={versionA=>setDraft({...draft,versionA})} items={fa?.forms||[]} label="Fighter A version"/></label></div><div className="fighter-versus">VS</div><div><FighterPicker label="Fighter B" value={draft.fighterBId} exclude={draft.fighterAId} onChange={fighterBId=>setDraft({...draft,fighterBId,versionB:''})}/><label>Version<Pick value={draft.versionB} onChange={versionB=>setDraft({...draft,versionB})} items={fb?.forms||[]} label="Fighter B version"/></label></div></div><h3 className="builder-title">Battle conditions</h3><div className="form-grid"><label>Battle type<Pick value={draft.battleType} onChange={battleType=>setDraft({...draft,battleType})} items={BATTLE_TYPES.map(value=>({value,label:BATTLE_TYPE_LABELS[value]}))} label="Battle type"/></label><label>Location<Pick value={draft.location} onChange={location=>setDraft({...draft,location})} items={BATTLE_LOCATIONS.map(value=>({value,label:LOCATION_LABELS[value]}))} label="Battle location"/></label>{draft.location==='custom'&&<label>Custom location<input value={draft.customLocation||''} onChange={e=>setDraft({...draft,customLocation:e.target.value})} maxLength={120}/></label>}<label>Speed<Pick value={draft.speed} onChange={speed=>setDraft({...draft,speed})} items={SPEED_RULES.map(value=>({value,label:SPEED_LABELS[value]}))} label="Speed rule"/></label><label>Knowledge<Pick value={draft.knowledge} onChange={knowledge=>setDraft({...draft,knowledge})} items={KNOWLEDGE_RULES.map(value=>({value,label:KNOWLEDGE_LABELS[value]}))} label="Knowledge rule"/></label><label>Prep time<Pick value={draft.prepTime} onChange={prepTime=>setDraft({...draft,prepTime})} items={PREP_TIMES.map(value=>({value,label:PREP_LABELS[value]}))} label="Prep time"/></label></div><div className="battle-toggles"><label><input type="checkbox" checked={draft.transformationsAllowed} onChange={e=>setDraft({...draft,transformationsAllowed:e.target.checked})}/>Transformations allowed</label><label><input type="checkbox" checked={draft.standardEquipment} onChange={e=>setDraft({...draft,standardEquipment:e.target.checked})}/>Standard equipment</label></div><label>Additional rules<textarea value={draft.notes||''} maxLength={1000} onChange={e=>setDraft({...draft,notes:e.target.value})} placeholder="Starting distance, environmental limits, verse equalization, or scenario-specific rules."/></label>{fa&&fb&&<section className="battle-summary"><small>BATTLE SUMMARY</small><div><strong>{fa.name}</strong><span>{draft.versionA||'Choose version'}</span><b>VS</b><strong>{fb.name}</strong><span>{draft.versionB||'Choose version'}</span></div><p>{BATTLE_TYPE_LABELS[draft.battleType]} · {location} · {SPEED_LABELS[draft.speed]} speed · {KNOWLEDGE_LABELS[draft.knowledge]} · {PREP_LABELS[draft.prepTime]} prep</p><p>{draft.transformationsAllowed?'Transformations allowed':'Transformations restricted'} · {draft.standardEquipment?'Standard equipment':'Equipment restricted'}</p></section>}<button className="primary full" disabled={busy||!valid}>Create battle</button></form></DialogContent></Dialog>}

function CharacterDialog({character,close,createBattle}:any){return <Dialog open={!!character} onOpenChange={o=>!o&&close()}><DialogContent className="modal"><DialogTitle>{character?.name}</DialogTitle><DialogDescription>{character?.series} · {character?.role}</DialogDescription>{character&&<><div className="character-record"><Avatar name={character.name} color={character.color}/><p>{character.ability}</p><h3>Canonical forms</h3><div className="chips">{character.forms.map((x:string)=><span key={x}>{x}</span>)}</div><h3>Story endpoint</h3><p>{character.endpoint}</p><a href={character.sourceUrl} target="_blank" rel="noreferrer">{character.sourceLabel}<ExternalLink size={14}/></a><small>Ability summaries are concise community references. Use the linked official source and cited episodes or chapters when debating specific feats.</small></div><button className="primary full" onClick={()=>createBattle(character.id)}>Use as fighter one</button></>}</DialogContent></Dialog>}
function Loading(){return <div className="empty-state">Loading…</div>}
